export const questions = [
  {title:'Что тебе нравится больше?', answers:['Разобраться, почему что-то работает','Создать текст, рисунок или видео','Помочь человеку или объяснить сложное','Организовать дело и увидеть результат']},
  {title:'Какой проект ты бы выбрал(а)?', answers:['Приложение, эксперимент или робот','Дизайн, фильм или творческий проект','Волонтёрство или занятия с младшими','Своя бизнес-идея или школьное событие']},
  {title:'Какая задача увлекает тебя?', answers:['Найти закономерность и проверить решение','Придумать необычный подход','Понять, что нужно другому человеку','Собрать команду и довести идею до конца']},
  {title:'Чему хочется научиться?', answers:['Программированию или исследованиям','Дизайну или созданию контента','Психологии или преподаванию','Предпринимательству или управлению']}
];
export const directions = [
  {title:'Технологии и исследования', examples:'Программирование · инженерия · анализ данных'},
  {title:'Творчество и коммуникации', examples:'Дизайн · медиа · создание контента'},
  {title:'Люди и помощь', examples:'Образование · психология · социальные проекты'},
  {title:'Организация и предпринимательство', examples:'Менеджмент · экономика · предпринимательство'}
];
export function getDirections(answers) {
  if (answers.length !== questions.length || answers.some(a => !Number.isInteger(a) || a < 0 || a >= directions.length)) throw new Error('Нужны четыре корректных ответа');
  const counts = directions.map((_,index) => answers.filter(a => a === index).length);
  const max = Math.max(...counts);
  return directions.filter((_,index) => counts[index] === max);
}
